import mongoose from 'mongoose';
const { Schema, model } = mongoose;

const userSchema = new Schema(
  {
    telegramId: { type: Number, required: true, unique: true },
    firstName: String,
    username: String,
    language: { type: String, enum: ['om', 'am', 'en'] },
    phone: String, // verified, the user's own number only
    role: { type: String, enum: ['USER', 'ADMIN'], default: 'USER' },
    referredBy: { type: Number, index: true },
  },
  { timestamps: true }
);

const lotterySchema = new Schema(
  {
    title: { type: String, required: true }, // "6 Gech EV Makina Equb"
    carName: { type: String, required: true }, // "BYD Leo Pard 7"
    carColor: { type: String, required: true }, // "Black"
    imageUrl: { type: String, required: true },
    ticketPrice: { type: Number, required: true, min: 1 },
    totalTickets: { type: Number, required: true, min: 1, max: 4000 },
    endsAt: { type: Date, required: true },
    featured: { type: Boolean, default: false },
    status: { type: String, enum: ['ACTIVE', 'CLOSED', 'DRAWN'], default: 'ACTIVE' },
    winnerNumber: Number,
    winnerUser: Number,
    drawnAt: Date,
  },
  { timestamps: true }
);

const bankAccountSchema = new Schema({
  bankName: { type: String, required: true },
  accountName: { type: String, required: true },
  accountNumber: { type: String, required: true },
  active: { type: Boolean, default: true },
  sortOrder: { type: Number, default: 0 },
});

const orderSchema = new Schema(
  {
    code: { type: String, required: true, unique: true }, // "swCX3hMzJT"
    user: { type: Number, required: true, index: true }, // telegramId
    lottery: { type: Schema.Types.ObjectId, ref: 'Lottery', required: true },
    fullName: { type: String, required: true },
    phone: { type: String, required: true },
    bankAccount: { type: Schema.Types.ObjectId, ref: 'BankAccount', default: null },
    senderAccount: String,
    receiptUrl: { type: String, required: true },
    total: { type: Number, required: true },
    status: {
      type: String,
      enum: ['PENDING', 'APPROVED', 'REJECTED'],
      default: 'PENDING',
      index: true,
    },
    rejectReason: String,
    reviewedAt: Date,
  },
  { timestamps: true }
);

// A document exists only while a number is HELD (order pending) or TAKEN (approved).
// No document = the number is free.
const ticketSchema = new Schema({
  lottery: { type: Schema.Types.ObjectId, ref: 'Lottery', required: true },
  number: { type: Number, required: true, min: 1 },
  order: { type: Schema.Types.ObjectId, ref: 'Order', required: true, index: true },
  user: { type: Number, required: true, index: true },
  status: { type: String, enum: ['HELD', 'TAKEN'], default: 'HELD' },
});
// This index is what makes selling the same number twice impossible.
ticketSchema.index({ lottery: 1, number: 1 }, { unique: true });

const notificationSchema = new Schema(
  {
    user: { type: Number, required: true },
    title: { type: String, required: true },
    body: { type: String, required: true },
    read: { type: Boolean, default: false },
  },
  { timestamps: true }
);
notificationSchema.index({ user: 1, read: 1 });

const broadcastSchema = new Schema(
  {
    text: { type: String, default: '' },
    hasPhoto: { type: Boolean, default: false },
    total: { type: Number, default: 0 },
    sent: { type: Number, default: 0 },
    blocked: { type: Number, default: 0 }, // users who blocked the bot
    failed: { type: Number, default: 0 },
    status: { type: String, enum: ['SENDING', 'DONE', 'INTERRUPTED'], default: 'SENDING' },
    by: Number,
  },
  { timestamps: true }
);

export const User = model('User', userSchema);
export const Lottery = model('Lottery', lotterySchema);
export const BankAccount = model('BankAccount', bankAccountSchema);
export const Order = model('Order', orderSchema);
export const Ticket = model('Ticket', ticketSchema);
export const Notification = model('Notification', notificationSchema);
export const Broadcast = model('Broadcast', broadcastSchema);
